main { max-width: 72rem; margin-inline: auto; padding: 0 1.5rem 4rem; }

.intro {
  display: grid;
  gap: 2.5rem;
  padding-block: 3rem 3.5rem;
  align-items: center;
}
@media (min-width: 56rem) {
  .intro { grid-template-columns: minmax(0, 1fr) 24rem; gap: 4rem; padding-block: 4.5rem 4rem; }
}

h1 {
  font-size: clamp(1.875rem, 1.4rem + 1.6vw, 2.5rem);
  line-height: 1.12;
  letter-spacing: -0.02em;
  font-weight: 700;
  max-width: 18ch;
}

.lede {
  margin: 1rem 0 0;
  font-size: 1.25rem; /* 20px, per brief */
  line-height: 1.45;
  color: var(--muted);
  max-width: 34ch;
}

.signin {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 10px;
  box-shadow: 0 1px 2px oklch(0.23 0.02 250 / 0.06), 0 4px 16px oklch(0.23 0.02 250 / 0.05);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.signin h2 { font-size: 1.25rem; font-weight: 650; margin-bottom: 0.25rem; }

.field { display: flex; flex-direction: column; gap: 0.375rem; }
.field > label, .label-row label { font-weight: 550; font-size: 0.9375rem; }
.label-row { display: flex; justify-content: space-between; align-items: baseline; gap: 1rem; }
.label-row a { font-size: 0.875rem; padding-block: 0.25rem; }

input[type="email"], input[type="password"], input[type="text"] {
  font: inherit;
  font-size: 1rem;
  height: 2.75rem;
  padding: 0 0.75rem;
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--edge);
  border-radius: 6px;
  width: 100%;
  min-width: 0;
}
input[aria-invalid="true"] { border-color: var(--danger); box-shadow: inset 0 0 0 1px var(--danger); }

.check {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 1.75rem;
  font-size: 0.9375rem;
  cursor: pointer;
  align-self: flex-start;
}
.check input { width: 1.125rem; height: 1.125rem; margin: 0; accent-color: var(--accent); }

.field-error, .form-status { margin: 0; font-size: 0.875rem; color: var(--danger); }
.field-error:empty, .form-status:empty { display: none; }

.btn-primary {
  font: inherit;
  font-weight: 600;
  height: 2.75rem;
  width: 100%;
  color: var(--surface);
  background: var(--accent);
  border: 0;
  border-radius: 6px;
  cursor: pointer;
  touch-action: manipulation;
  transition: background-color 150ms var(--ease);
}
.btn-primary:active { background: var(--accent-press); }
@media (hover: hover) { .btn-primary:hover { background: var(--accent-press); } }
.btn-primary[aria-disabled="true"] { cursor: progress; background: var(--accent-press); }

/* ---------- The status mark: shape + word + colour, never colour alone ---------- */

.mark::before {
  content: "";
  display: inline-block;
  flex: none;
  width: 0.5625rem;
  height: 0.5625rem;
  margin-inline-end: 0.4375rem;
  background: currentColor;
}
.mark { display: inline-flex; align-items: center; }
.mark-paid { color: var(--paid); }                    /* filled square */
.mark-open { color: var(--open); }
.mark-open::before { background: none; border: 1.5px solid currentColor; } /* hollow square */
.mark-overdue { color: var(--danger); font-weight: 600; }
.mark-overdue::before { width: 0.6875rem; clip-path: polygon(50% 0, 100% 100%, 0 100%); } /* triangle */
.mark-error::before { transform: rotate(45deg) scale(0.85); }            /* diamond */

/* ---------- Invoice preview table ---------- */

.preview-head { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0.25rem 1rem; margin-bottom: 0.75rem; }
.preview-head h2 { font-size: 1.125rem; font-weight: 650; }
.preview-head p { margin: 0; font-size: 0.875rem; color: var(--muted); }

.table-scroll {
  max-height: min(30rem, 70dvh);
  overflow: auto;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 8px;
  scroll-padding-block-start: 2rem;   /* sticky header height */
  scroll-padding-inline-start: 13rem; /* sticky client column */
}

table {
  width: 100%;
  min-width: 46rem;
  table-layout: fixed;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 0.875rem;
  font-variant-numeric: tabular-nums;
}
.c-client { width: 28%; }
.c-number { width: 11%; }
.c-date   { width: 12%; }
.c-amount { width: 14%; }
.c-status { width: 23%; }

th, td { text-align: start; border-bottom: 1px solid var(--line); }
.num { text-align: end; }

th {
  position: sticky;
  inset-block-start: 0;
  z-index: var(--z-sticky);
  padding: 0;
  background: var(--head);
  border-bottom-color: var(--edge);
  font-weight: 600;
}
th button {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  width: 100%;
  height: 2rem;
  padding: 0 0.75rem;
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  cursor: pointer;
}
th.num button { justify-content: flex-end; }
th button:focus-visible { outline-offset: -3px; }
@media (hover: hover) { th button:hover { background: var(--line); } }
.dir { display: inline-block; width: 0.75rem; color: var(--muted); }
th[aria-sort="ascending"] .dir::after { content: "↑"; }
th[aria-sort="descending"] .dir::after { content: "↓"; }

td {
  height: 2rem;
  padding: 0 0.75rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
tbody tr:last-child td { border-bottom: 0; }
td.muted { color: var(--muted); }

th:first-child, td:first-child { position: sticky; inset-inline-start: 0; }
td:first-child { background: var(--surface); z-index: 1; }
th:first-child { z-index: var(--z-sticky-corner); }

@media (hover: hover) { tbody tr:hover td { background: var(--head); } }

