// ---------- What's new ----------

const toggle = document.getElementById('whats-new-toggle');
const drawer = document.getElementById('whats-new');

function setDrawer(open) {
  toggle.setAttribute('aria-expanded', open);
  drawer.classList.toggle('is-open', open);
}
toggle.addEventListener('click', () => setDrawer(toggle.getAttribute('aria-expanded') !== 'true'));
document.addEventListener('keydown', (e) => {
  if (e.key !== 'Escape' || toggle.getAttribute('aria-expanded') !== 'true') return;
  if (drawer.contains(document.activeElement) || document.activeElement === toggle) {
    setDrawer(false);
    toggle.focus();
  }
});

// ---------- Sign in ----------

const form = document.getElementById('signin');
const email = document.getElementById('email');
const password = document.getElementById('password');
const submit = document.getElementById('signin-submit');
const formStatus = document.getElementById('form-status');
let busy = false;

function problem(input) {
  if (input === email) {
    if (!email.value.trim()) return 'Enter your email address.';
    if (email.validity.typeMismatch) return 'Enter an email address like name@yourfirm.co.uk.';
  }
  if (input === password && !password.value) return 'Enter your password.';
  return '';
}

function show(input) {
  const msg = problem(input);
  document.getElementById(input.id + '-error').textContent = msg;
  input.toggleAttribute('aria-invalid', !!msg);
  if (msg) input.setAttribute('aria-invalid', 'true');
  return !msg;
}

for (const input of [email, password]) {
  input.addEventListener('input', () => {
    input.dataset.dirty = '1';
    // Clear an error as soon as it's fixed; never raise a new one mid-typing.
    if (input.hasAttribute('aria-invalid') && !problem(input)) show(input);
  });
  input.addEventListener('blur', () => { if (input.dataset.dirty) show(input); });
}

document.getElementById('show-password').addEventListener('change', (e) => {
  password.type = e.target.checked ? 'text' : 'password';
});

form.addEventListener('submit', async (e) => {
  e.preventDefault();
  if (busy) return;
  formStatus.textContent = '';

  const invalid = [email, password].filter((input) => !show(input));
  if (invalid.length) { invalid[0].focus(); return; } // error is read via aria-describedby

  busy = true;
  submit.setAttribute('aria-disabled', 'true');
  submit.textContent = 'Signing in…';
  try {
    // ponytail: /session and /invoices are assumed backend routes
    const res = await fetch(form.action, { method: 'POST', body: new FormData(form), credentials: 'same-origin' });
    if (res.ok) { location.assign('/invoices'); return; }
    formStatus.textContent = res.status === 401
      ? "That email and password don't match. Check both and try again."
      : "Tallyhouse couldn't sign you in just now. Your details are still here, so try again in a moment.";
  } catch {
    formStatus.textContent = "Tallyhouse couldn't be reached. Check your connection, then try again.";
  }
  busy = false;
  submit.removeAttribute('aria-disabled');
  submit.textContent = 'Sign in';
});

// ---------- Invoice preview ----------

// Seeded so the sample list is identical on every load (sort state lives in the URL).
function mulberry32(a) {
  return () => {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const DAY = 864e5;
const clients = [
  'Harbour Street Bakery', 'Okafor & Lin Dental', 'Pemberton Joinery', 'Blue Anchor Lettings',
  'Marsh Lane Veterinary Practice', 'Kestrel Print Co.', 'Ashdown Physiotherapy', 'Greenway Landscaping',
  'Northgate Opticians', 'Riverside Cycle Works', 'Hollis & Grant Solicitors', 'Moorfield Day Nursery',
  'Copperleaf Café', 'Whitcombe Electrical',
];

const rnd = mulberry32(2186);
const today = new Date(); today.setHours(0, 0, 0, 0);
const invoices = Array.from({ length: 40 }, (_, i) => {
  const issued = new Date(today - (i * 2 + Math.floor(rnd() * 2)) * DAY);
  const due = new Date(+issued + (rnd() < 0.6 ? 30 : 14) * DAY);
  const late = Math.round((today - due) / DAY);
  const paid = late > 0 ? rnd() < 0.7 : rnd() < 0.25;
  return {
    client: clients[Math.floor(rnd() * clients.length)],
    number: 'TH-' + (2186 - i),
    issued, due,
    amount: Math.round((180 + rnd() * 4200) * 100) / 100,
    status: paid ? 'paid' : late > 0 ? 'overdue' : 'open',
    late,
  };
});

const money = new Intl.NumberFormat('en-GB', { style: 'currency', currency: 'GBP' });
const date = new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
const statusRank = { overdue: 0, open: 1, paid: 2 };
const compare = {
  client: (a, b) => a.client.localeCompare(b.client),
  number: (a, b) => a.number.localeCompare(b.number, undefined, { numeric: true }),
  issued: (a, b) => a.issued - b.issued,
  due: (a, b) => a.due - b.due,
  amount: (a, b) => a.amount - b.amount,
  status: (a, b) => statusRank[a.status] - statusRank[b.status] || b.late - a.late,
};

const tbody = document.querySelector('#invoices tbody');
const headers = [...document.querySelectorAll('#invoices th')];
const params = new URLSearchParams(location.search);
let sortKey = compare[params.get('sort')] ? params.get('sort') : 'issued';
let sortDir = params.get('dir') === 'asc' ? 'asc' : params.get('dir') === 'desc' ? 'desc' : (sortKey === 'issued' ? 'desc' : 'asc');

function cell(text, className) {
  const td = document.createElement('td');
  td.textContent = text;
  if (className) td.className = className;
  return td;
}

function statusCell(inv) {
  const td = document.createElement('td');
  const span = document.createElement('span');
  span.className = 'mark mark-' + inv.status;
  span.textContent = inv.status === 'overdue' ? `Overdue ${inv.late}d`
    : inv.status === 'open' ? (inv.late === 0 ? 'Open, due today' : `Open, due in ${-inv.late}d`)
    : 'Paid';
  td.append(span);
  return td;
}

function render() {
  const sign = sortDir === 'asc' ? 1 : -1;
  const rows = [...invoices].sort((a, b) => sign * compare[sortKey](a, b)).map((inv) => {
    const tr = document.createElement('tr');
    const client = cell(inv.client);
    client.title = inv.client; // full name when truncated
    tr.append(
      client,
      cell(inv.number, 'muted'),
      cell(date.format(inv.issued)),
      cell(date.format(inv.due)),
      cell(money.format(inv.amount), 'num'),
      statusCell(inv),
    );
    return tr;
  });
  tbody.replaceChildren(...rows);
  for (const th of headers) {
    if (th.dataset.key === sortKey) th.setAttribute('aria-sort', sortDir === 'asc' ? 'ascending' : 'descending');
    else th.removeAttribute('aria-sort');
  }
}

for (const th of headers) {
  th.querySelector('button').addEventListener('click', () => {
    const key = th.dataset.key;
    sortDir = key === sortKey ? (sortDir === 'asc' ? 'desc' : 'asc') : 'asc';
    sortKey = key;
    params.set('sort', sortKey);
    params.set('dir', sortDir);
    history.replaceState(null, '', '?' + params);
    render();
  });
}

render();

